/* @lc app=leetcode id=1959 lang=kotlin */
class Solution { fun minSpaceWastedKResizing(nums: IntArray, k: Int): Int = IntArray(nums.size * (k + 1)) { -1 }.let { memo -> DeepRecursiveFunction<Pair<Int, Int>, Int> { (i, rsz) -> if (rsz < 0) 1e9.toInt() else if (i == nums.size) 0 else memo[i * (k + 1) + rsz].takeIf { it != -1 } ?: (i until nums.size).fold(Triple(1e9.toInt(), 0, 0)) { acc, r -> maxOf(acc.second, nums[r]).let { newMx -> (acc.third + nums[r]).let { newSm -> Triple(minOf(acc.first, newMx * (r - i + 1) - newSm + callRecursive(r + 1 to rsz - 1)), newMx, newSm) } } }.first.also { memo[i * (k + 1) + rsz] = it } }.invoke(0 to k) } }